import React, { useEffect, useState } from "react";


function LevelsPage() {
  const [students, setStudents] = useState([]);

  useEffect(() => {
    fetch("http://localhost:5000/students")
      .then(res => res.json())
      .then(data => setStudents(data));
  }, []);

  return (
    <div style={{
  backgroundColor: "black",
  color: "yellow",
  fontSize: "20px",
}}>
      <h1>Student Table</h1>

      <table border='3' >
        <thead>
          <tr>
            <th>ID</th>
            <th>Level</th>
            <th>Tittle</th>
            <th>Discription</th>
            <th>Action</th> 
          </tr>
        </thead>

        <tbody>
          {students.map((stu) => (
            <tr key={stu.id}>
              <td>{stu.id}</td>
              <td>{stu.level}</td>
              <td>{stu.title}</td>
              <td>{stu.description}</td>
              <td> Start</td>

            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default LevelsPage;
